/// Index into COEFFICIENTS array: offset[n] = index of first record for degree n
/// Degree n has (n+1) records (m = 0..n), so offset[n] = Sum_{k=2}^{n-1}(k+1)
static constexpr int degreeOffset(int n) {
    // offset[2] = 0, offset[3] = 3, offset[4] = 7, ...
    // offset[n] = (n*(n+1)/2) - 3  for n >= 2
    return (n * (n + 1)) / 2 - 3;
}

